// Writes R/extendr-wrappers.R from the metadata of the extendr module
// `rtemis_ml`. The Makevars run it after building the static library, except
// in webR builds.
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let wrapper_path = "../R/extendr-wrappers.R";
    let header = "\
        # Generated by extendr: Do not edit by hand\n\
        # nolint start\n\
        \n\
        #' @usage NULL\n\
        #' @useDynLib rtemis.ml, .registration = TRUE\n\
        NULL\n\
        \n\
    ";
    let footer = "# nolint end\n";
    let wrappers = rtemis_ml_r::get_rtemis_ml_metadata()
        .make_r_wrappers(true, "rtemis.ml")
        .map_err(|e| format!("failed to generate wrappers: {e}"))?;
    std::fs::write(wrapper_path, format!("{header}{wrappers}{footer}"))
        .map_err(|e| format!("failed to write {wrapper_path}: {e}"))?;
    Ok(())
}
